package com.flowgate.control.promotion;

import com.flowgate.control.portal.*;
import com.flowgate.control.commerce.*;
import com.flowgate.control.security.ApiFailure;
import com.flowgate.control.service.AuditService;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.springframework.dao.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import org.springframework.scheduling.annotation.Scheduled;
import static com.flowgate.control.portal.PortalStore.*;
import static com.flowgate.control.service.BusinessInputs.*;

/** 持久受理、异步创单与运营。库存/权益槽/Outbox同事务，Lua候选永不直接返回202。 */
@Service
public class PromotionService {
    private final PortalStore db;private final PortalOwnershipService owner;private final PromotionReadiness ready;private final PromotionAdminService admin;private final PromotionCandidateGate gate;private final MarketCatalogService market;private final OrderService orders;private final AuditService audit;private final TransactionTemplate tx,read;private final long started=System.nanoTime();
    public PromotionService(PortalStore db,PortalOwnershipService owner,PromotionReadiness ready,PromotionAdminService admin,PromotionCandidateGate gate,MarketCatalogService market,OrderService orders,AuditService audit,PlatformTransactionManager manager){this.db=db;this.owner=owner;this.ready=ready;this.admin=admin;this.gate=gate;this.market=market;this.orders=orders;this.audit=audit;tx=new TransactionTemplate(manager);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);tx.setTimeout(8);read=new TransactionTemplate(manager);read.setReadOnly(true);read.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);read.setTimeout(8);}
    private ApiFailure conflict(String code,String message){return new ApiFailure(409,code,message);}
    private Map<String,Object> existing(long user,long promo,String request,String fingerprint){var old=db.one("SELECT * FROM fg_promo_purchase_intent WHERE promotion_id=? AND principal_id=?",promo,user);if(old!=null&&(!request.equals(old.get("client_request_id"))||!fingerprint.equals(old.get("request_fingerprint"))))throw conflict("PROMOTION_ALREADY_CLAIMED","每人每场只能受理一次，请查看原抢购记录");return old;}
    public Map<String,Object> view(Map<String,Object> i){var result=new LinkedHashMap<String,Object>();result.put("intentId",i.get("id"));result.put("promotionId",i.get("promotion_id"));result.put("status",i.get("status"));result.put("amountCents",i.get("price_cents"));result.put("quotaUnits",i.get("quota_units"));result.put("periodUtc",i.get("period_yyyymm"));result.put("creationDeadlineAt",i.get("creation_deadline_at"));result.put("applicationId",i.get("application_id"));result.put("order",i.get("order_id")==null?null:orders.summary(db.need("SELECT * FROM fg_order WHERE id=?",i.get("order_id"))));return result;}
    public Object mine(long user,long promotion){ready.require();var i=db.one("SELECT * FROM fg_promo_purchase_intent WHERE promotion_id=? AND principal_id=?",promotion,user);return i==null?Map.of("status","NOT_ACCEPTED","message","尚未持久受理，请稍后查询或提交"):view(i);}
    public Object intent(long user,long id){ready.require();var i=db.need("SELECT * FROM fg_promo_purchase_intent WHERE id=? AND principal_id=?",id,user);owner.app(user,n(i,"application_id"));return view(i);}
    public Object claim(long user,long promotion,Map<String,Object> b){ready.require();fields(b,"applicationId","clientRequestId");long app=number(b.get("applicationId"),Long.MAX_VALUE,"应用");String request=text(b.get("clientRequestId"),"请求号",64);require(request.matches("[A-Za-z0-9_-]+"),"VALIDATION_ERROR","请求号格式无效");String fingerprint=CommerceEvent.hash(user+":"+promotion+":"+app);
        owner.app(user,app);var old=existing(user,promotion,request,fingerprint);if(old!=null)return view(old);
        var publicSnapshot=admin.publicDetail(promotion);var candidate=gate.acquire(promotion,n(publicSnapshot,"epoch"),user);AtomicBoolean rolledBack=new AtomicBoolean();
        for(int attempt=0;;attempt++)try{return tx.execute(status->{TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCompletion(int completion){rolledBack.set(completion==STATUS_ROLLED_BACK);}});
            // 1. APP→Slot→活动共享锁→Intent→Stock；身份和冻结月份从MySQL复核，缓存价不参与交易。
            var application=db.need("SELECT * FROM fg_application WHERE id=? FOR UPDATE",app);owner.lockAppOwner(user,app);var developer=db.need("SELECT status FROM fg_developer WHERE id=? FOR SHARE",application.get("developer_id"));if(!"ACTIVE".equals(application.get("status"))||!"ACTIVE".equals(developer.get("status")))throw conflict("APP_DISABLED","应用或工作区已停用");
            long api=n(publicSnapshot,"api_id");String period=s(publicSnapshot,"period_yyyymm");db.update("INSERT INTO fg_api_entitlement_slot(application_id,api_id,period_yyyymm) VALUES(?,?,?) ON DUPLICATE KEY UPDATE application_id=application_id",app,api,period);var slot=db.need("SELECT * FROM fg_api_entitlement_slot WHERE application_id=? AND api_id=? AND period_yyyymm=? FOR UPDATE",app,api,period);
            var p=db.need("SELECT * FROM fg_promotion WHERE id=? FOR SHARE",promotion);Instant now=db.nowUtc();if(n(p,"epoch")!=candidate.epoch()||!"RUNNING".equals(p.get("status"))||now.isBefore(OrderService.instant(p,"begins_at"))||!now.isBefore(OrderService.instant(p,"ends_at")))throw conflict("PROMOTION_NOT_RUNNING","活动未开始、已结束或正在恢复，请刷新");
            if(api!=n(p,"api_id")||!period.equals(p.get("period_yyyymm")))throw conflict("PROMOTION_VERSION_CONFLICT","活动快照已更新");oldCheck(user,promotion,request,fingerprint);
            if(!"AVAILABLE".equals(slot.get("state")))throw conflict("BASE_ENTITLEMENT_CONFLICT","该应用/API/月已有权益或待付款订单");market.paidOffer(n(p,"sku_id"));String policy=period.equals(PortalApplicationService.period(now))?"CURRENT_MONTH":"NEXT_MONTH";var window=OrderStateMachine.window(period,policy,now);
            if(db.one("SELECT id FROM fg_subscription WHERE application_id=? AND effective_at<? AND expires_at>? LIMIT 1",app,Timestamp.from(window.end()),Timestamp.from(window.start()))!=null)throw conflict("LEGACY_SUBSCRIPTION_CONFLICT","该月已有旧版订阅，请使用独立应用");
            Instant deadline=now.plusSeconds(n(p,"order_creation_ttl_seconds"));if(deadline.isAfter(window.end().minusSeconds(300)))deadline=window.end().minusSeconds(300);
            // 2. 唯一Intent先建，Stock最后条件更新；任何冲突整笔回滚，不能留下202或孤立槽。
            long id=db.insert("INSERT INTO fg_promo_purchase_intent(promotion_id,principal_id,application_id,api_id,sku_id,period_yyyymm,client_request_id,request_fingerprint,activity_epoch,sku_revision,quota_units,price_cents,effective_at,expires_at,creation_deadline_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",promotion,user,app,api,p.get("sku_id"),period,request,fingerprint,candidate.epoch(),p.get("sku_revision"),p.get("quota_units"),p.get("promo_price_cents"),Timestamp.from(window.start()),Timestamp.from(window.end()),Timestamp.from(deadline));
            if(db.update("UPDATE fg_promo_stock SET reserved=reserved+1,version=version+1 WHERE promotion_id=? AND reserved+sold<total_stock",promotion)!=1)throw conflict("PROMOTION_SOLD_OUT","本场名额已用完");
            if(db.update("UPDATE fg_api_entitlement_slot SET state='HELD',holder_type='PROMO',holder_id=?,version=version+1 WHERE application_id=? AND api_id=? AND period_yyyymm=? AND state='AVAILABLE' AND version=?",id,app,api,period,slot.get("version"))!=1)throw conflict("SLOT_CONFLICT","权益槽已变化");
            var event=new PromotionIntentEvent(1,UUID.randomUUID().toString(),id,promotion,candidate.epoch(),now.toString());db.insert("INSERT INTO fg_promo_outbox(event_id,intent_id,payload_json) VALUES(?,?,?)",event.eventId(),id,event.canonical());return view(db.need("SELECT * FROM fg_promo_purchase_intent WHERE id=?",id));
        });}catch(PessimisticLockingFailureException retry){if(rolledBack.get()&&attempt<2){rolledBack.set(false);continue;}if(rolledBack.get())gate.compensate(candidate);throw retry;}
        catch(RuntimeException failure){
            // 3. 仅确认回滚才补偿原epoch/token。COMMIT结果未知时先查唯一Intent，仍未知则不返软名额。
            if(rolledBack.get())gate.compensate(candidate);
            Map<String,Object> recovered;try{recovered=existing(user,promotion,request,fingerprint);}catch(org.springframework.dao.DataAccessException unknown){throw new ApiFailure(503,"PROMOTION_ACCEPTANCE_UNKNOWN","受理结果暂不可知，请通过我的抢购查询");}
            if(recovered!=null)return view(recovered);if(failure instanceof DuplicateKeyException)throw conflict("IDEMPOTENCY_CONFLICT","请求号已用于其他活动或应用");throw failure;
        }
    }
    private void oldCheck(long user,long promotion,String request,String fingerprint){if(existing(user,promotion,request,fingerprint)!=null)throw conflict("PROMOTION_ALREADY_CLAIMED","原请求已经受理，请读取我的抢购");}
    private Map<String,Object> lockIntent(Map<String,Object> seed){db.need("SELECT id FROM fg_application WHERE id=? FOR UPDATE",seed.get("application_id"));db.need("SELECT * FROM fg_api_entitlement_slot WHERE application_id=? AND api_id=? AND period_yyyymm=? FOR UPDATE",seed.get("application_id"),seed.get("api_id"),seed.get("period_yyyymm"));return db.need("SELECT * FROM fg_promo_purchase_intent WHERE id=? FOR UPDATE",seed.get("id"));}
    private void validate(PromotionIntentEvent e,Map<String,Object> i){var source=db.need("SELECT * FROM fg_promo_outbox WHERE event_id=?",e.eventId());if(n(source,"intent_id")!=e.intentId()||!e.equals(PromotionIntentEvent.parse(s(source,"payload_json")))||n(i,"promotion_id")!=e.promotionId()||n(i,"activity_epoch")!=e.activityEpoch())throw conflict("PROMO_EVENT_CONFLICT","意图消息与数据库权威来源不一致");var p=db.need("SELECT * FROM fg_promotion WHERE id=?",e.promotionId());if(n(i,"sku_id")!=n(p,"sku_id")||n(i,"api_id")!=n(p,"api_id")||n(i,"quota_units")!=n(p,"quota_units")||n(i,"price_cents")!=n(p,"promo_price_cents")||n(i,"sku_revision")!=n(p,"sku_revision")||!Objects.equals(i.get("period_yyyymm"),p.get("period_yyyymm")))throw conflict("PROMO_EVENT_CONFLICT","活动冻结快照不一致");}
    public String process(String payload){var e=PromotionIntentEvent.parse(payload);return tx.execute(status->{var seed=db.need("SELECT * FROM fg_promo_purchase_intent WHERE id=?",e.intentId());var i=lockIntent(seed);validate(e,i);var consumed=db.one("SELECT * FROM fg_promo_event_consumed WHERE event_id=? OR intent_id=?",e.eventId(),e.intentId());if(consumed!=null){if(!e.eventId().equals(consumed.get("event_id"))||!e.fingerprint().equals(consumed.get("payload_sha256")))throw conflict("PROMO_EVENT_CONFLICT","已消费消息指纹冲突");return "DUPLICATE";}
        // 4. ACCEPTED只有在创单期限内转为B订单；活动暂停/结束不撤销已经持久受理的资格。
        String state=s(i,"status");if(!"ACCEPTED".equals(state)){if("ORDER_READY".equals(state)&&i.get("order_id")!=null){consumed(e,"ALREADY_APPLIED");return "ALREADY_APPLIED";}consumed(e,"IGNORED_TERMINAL");return "IGNORED_TERMINAL";}
        if(!db.nowUtc().isBefore(OrderService.instant(i,"creation_deadline_at"))){expireLocked(i);consumed(e,"IGNORED_TERMINAL");return "IGNORED_TERMINAL";}
        var slot=db.need("SELECT * FROM fg_api_entitlement_slot WHERE application_id=? AND api_id=? AND period_yyyymm=?",i.get("application_id"),i.get("api_id"),i.get("period_yyyymm"));if(!"HELD".equals(slot.get("state"))||!"PROMO".equals(slot.get("holder_type"))||n(slot,"holder_id")!=e.intentId())throw conflict("PROMO_SLOT_CONFLICT","原意图权益槽不一致");
        var app=db.need("SELECT developer_id FROM fg_application WHERE id=?",i.get("application_id"));var p=db.need("SELECT pay_ttl_seconds FROM fg_promotion WHERE id=?",e.promotionId());Instant deadline=db.nowUtc().plusSeconds(n(p,"pay_ttl_seconds")),last=OrderService.instant(i,"expires_at").minusSeconds(300);if(deadline.isAfter(last))deadline=last;if(!db.nowUtc().isBefore(deadline))throw conflict("PROMO_PERIOD_CLOSED","固定权益月份已结束");
        long order=db.insert("INSERT INTO fg_order(order_no,principal_id,developer_id,application_id,api_id,sku_id,period_yyyymm,sku_revision,price_cents,units_snapshot,source,promo_intent_id,client_request_id,request_fingerprint,pay_deadline_at,effective_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,'PROMOTION',?,?,?,?,?,?)",UUID.randomUUID().toString(),i.get("principal_id"),app.get("developer_id"),i.get("application_id"),i.get("api_id"),i.get("sku_id"),i.get("period_yyyymm"),i.get("sku_revision"),i.get("price_cents"),i.get("quota_units"),e.intentId(),"pr_"+UUID.randomUUID(),i.get("request_fingerprint"),Timestamp.from(deadline),i.get("effective_at"),i.get("expires_at"));
        if(db.update("UPDATE fg_api_entitlement_slot SET holder_type='ORDER',holder_id=?,version=version+1 WHERE application_id=? AND api_id=? AND period_yyyymm=? AND state='HELD' AND holder_type='PROMO' AND holder_id=?",order,i.get("application_id"),i.get("api_id"),i.get("period_yyyymm"),e.intentId())!=1)throw conflict("PROMO_SLOT_CONFLICT","意图转订单权益槽失败");
        db.update("UPDATE fg_promo_purchase_intent SET status='ORDER_READY',order_id=?,version=version+1 WHERE id=? AND status='ACCEPTED'",order,e.intentId());orders.transition(order,null,"PENDING_PAYMENT","WORKER",null,"PROMOTION_ORDER_CREATED");consumed(e,"APPLIED");return "CONSUMED";
    });}
    private void consumed(PromotionIntentEvent e,String result){db.update("INSERT INTO fg_promo_event_consumed(event_id,intent_id,payload_sha256,result) VALUES(?,?,?,?)",e.eventId(),e.intentId(),e.fingerprint(),result);}
    private void expireLocked(Map<String,Object> i){if(!"ACCEPTED".equals(i.get("status")))return;long id=n(i,"id");if(db.update("UPDATE fg_promo_purchase_intent SET status='EXPIRED',version=version+1 WHERE id=? AND status='ACCEPTED'",id)!=1)throw conflict("PROMO_STATE_CONFLICT","意图状态已变化");if(db.update("UPDATE fg_promo_stock SET reserved=reserved-1,version=version+1 WHERE promotion_id=? AND reserved>=1",i.get("promotion_id"))!=1)throw conflict("PROMOTION_STOCK_CONFLICT","库存预留不一致");if(db.update("UPDATE fg_api_entitlement_slot SET state='AVAILABLE',holder_type=NULL,holder_id=NULL,version=version+1 WHERE application_id=? AND api_id=? AND period_yyyymm=? AND state='HELD' AND holder_type='PROMO' AND holder_id=?",i.get("application_id"),i.get("api_id"),i.get("period_yyyymm"),id)!=1)throw conflict("PROMO_SLOT_CONFLICT","超时意图权益槽不一致");}
    @Scheduled(fixedDelay=1000) public void expire(){if(!ready.available())return;try{for(var seed:db.rows("SELECT * FROM fg_promo_purchase_intent WHERE status='ACCEPTED' AND creation_deadline_at<=UTC_TIMESTAMP(3) ORDER BY creation_deadline_at,id LIMIT 20"))tx.executeWithoutResult(status->{var i=lockIntent(seed);if("ACCEPTED".equals(i.get("status"))&&!db.nowUtc().isBefore(OrderService.instant(i,"creation_deadline_at")))expireLocked(i);});}catch(RuntimeException unavailable){org.slf4j.LoggerFactory.getLogger(getClass()).warn("PROMO_EXPIRY_PENDING");}}
    public List<Map<String,Object>> claimOutbox(){return tx.execute(status->{var rows=db.rows("SELECT * FROM fg_promo_outbox WHERE ((status IN ('NEW','FAILED') AND next_attempt_at<=UTC_TIMESTAMP(3)) OR (status='IN_FLIGHT' AND lease_until<UTC_TIMESTAMP(3))) AND attempt_count<8 ORDER BY id LIMIT 2 FOR UPDATE SKIP LOCKED");for(var row:rows){String lease=UUID.randomUUID().toString();db.update("UPDATE fg_promo_outbox SET status='IN_FLIGHT',lease_owner=?,lease_until=DATE_ADD(UTC_TIMESTAMP(3),INTERVAL 30 SECOND),attempt_count=attempt_count+1 WHERE id=?",lease,row.get("id"));row.put("lease_owner",lease);}return rows;});}
    public void published(Map<String,Object> row){db.update("UPDATE fg_promo_outbox SET status='SENT',lease_owner=NULL,lease_until=NULL,next_attempt_at=UTC_TIMESTAMP(3),last_error_code=NULL WHERE id=? AND status='IN_FLIGHT' AND lease_owner=? AND lease_until>=UTC_TIMESTAMP(3)",row.get("id"),row.get("lease_owner"));}
    public void failed(Map<String,Object> row,boolean permanent){db.update("UPDATE fg_promo_outbox SET status=?,lease_owner=NULL,lease_until=NULL,next_attempt_at=DATE_ADD(UTC_TIMESTAMP(3),INTERVAL 5 SECOND),last_error_code=? WHERE id=? AND status='IN_FLIGHT' AND lease_owner=? AND lease_until>=UTC_TIMESTAMP(3)",permanent?"FAILED_PERMANENT":"FAILED",permanent?"INVALID_EVENT":"BROKER_UNAVAILABLE",row.get("id"),row.get("lease_owner"));}
    public Object events(long promotion){ready.require();return db.rows("SELECT o.id,o.event_id,o.intent_id,o.status,o.attempt_count,o.last_error_code,c.consumed_at FROM fg_promo_outbox o JOIN fg_promo_purchase_intent i ON i.id=o.intent_id LEFT JOIN fg_promo_event_consumed c ON c.event_id=o.event_id WHERE i.promotion_id=? ORDER BY o.id DESC LIMIT 100",promotion);}
    public Object replay(String event,long actor){ready.require();if(System.nanoTime()-started<java.util.concurrent.TimeUnit.SECONDS.toNanos(300))throw conflict("REPLAY_COOLDOWN","节点启动后300秒内不补投");return tx.execute(status->{var row=db.need("SELECT o.* FROM fg_promo_outbox o WHERE event_id=? FOR UPDATE",event);if(!"SENT".equals(row.get("status"))||db.nowUtc().isBefore(OrderService.instant(row,"next_attempt_at").plusSeconds(300))||db.one("SELECT event_id FROM fg_promo_event_consumed WHERE event_id=?",event)!=null)throw conflict("REPLAY_NOT_ELIGIBLE","仅超过300秒且未消费SENT原事件可补投");var e=PromotionIntentEvent.parse(s(row,"payload_json"));if(!e.eventId().equals(event)||e.intentId()!=n(row,"intent_id"))throw conflict("PROMO_EVENT_CONFLICT","事件来源不一致");validate(e,db.need("SELECT * FROM fg_promo_purchase_intent WHERE id=?",e.intentId()));if(db.update("UPDATE fg_promo_outbox SET status='NEW',attempt_count=0,next_attempt_at=UTC_TIMESTAMP(3) WHERE id=? AND status='SENT'",row.get("id"))!=1)throw conflict("REPLAY_NOT_ELIGIBLE","事件已被其他操作处理");audit.record(actor,"REPLAY_PROMO_EVENT","promotion",event,null,"原eventId补投，指纹="+e.fingerprint());return Map.of("status","QUEUED");});}
    public Object reconciliation(long promotion){ready.require();return read.execute(status->{var p=admin.detail(promotion);var intents=db.rows("SELECT i.*,o.source,o.promo_intent_id,o.status order_status,o.principal_id order_principal,o.application_id order_app,o.api_id order_api,o.sku_id order_sku,o.period_yyyymm order_period,o.price_cents order_price,o.units_snapshot order_units,p.id payment_id,p.amount_cents,c.event_id consumed_id FROM fg_promo_purchase_intent i LEFT JOIN fg_order o ON o.id=i.order_id LEFT JOIN fg_payment_record p ON p.order_id=o.id LEFT JOIN fg_promo_event_consumed c ON c.intent_id=i.id WHERE i.promotion_id=? ORDER BY i.id LIMIT 1001",promotion);if(intents.size()>1000)return Map.of("status","UNKNOWN","reason","超过1000条检查范围");long reserved=0,sold=0,gaps=0,pending=0;for(var i:intents){String state=s(i,"status");if(Set.of("ACCEPTED","ORDER_READY").contains(state))reserved++;if(Set.of("PAID","REFUNDED").contains(state)){sold++;if(i.get("payment_id")==null||n(i,"amount_cents")!=n(i,"price_cents"))gaps++;}if("ACCEPTED".equals(state))pending++;if(i.get("order_id")!=null&&(!"PROMOTION".equals(i.get("source"))||n(i,"promo_intent_id")!=n(i,"id")||i.get("consumed_id")==null))gaps++;
            var slot=db.one("SELECT * FROM fg_api_entitlement_slot WHERE application_id=? AND api_id=? AND period_yyyymm=?",i.get("application_id"),i.get("api_id"),i.get("period_yyyymm"));if("ACCEPTED".equals(state)&&(slot==null||!"HELD".equals(slot.get("state"))||!"PROMO".equals(slot.get("holder_type"))||n(slot,"holder_id")!=n(i,"id")))gaps++;
            // 5. 对账检查冻结订单、付款Outbox及真实Grant链，不以单纯数量相等冒充闭环。
            if(i.get("order_id")!=null){
                if(n(i,"order_principal")!=n(i,"principal_id")||n(i,"order_app")!=n(i,"application_id")||n(i,"order_api")!=n(i,"api_id")||n(i,"order_sku")!=n(i,"sku_id")||n(i,"order_price")!=n(i,"price_cents")||n(i,"order_units")!=n(i,"quota_units")||!Objects.equals(i.get("order_period"),i.get("period_yyyymm")))gaps++;
                if("ORDER_READY".equals(state)&&(slot==null||!"HELD".equals(slot.get("state"))||!"ORDER".equals(slot.get("holder_type"))||n(slot,"holder_id")!=n(i,"order_id")))gaps++;
                if(Set.of("PAID","REFUNDED").contains(state)&&db.one("SELECT id FROM fg_business_outbox WHERE aggregate_id=?",i.get("order_id"))==null)gaps++;
                var grant=db.one("SELECT * FROM fg_entitlement_grant WHERE source_type='PAID_ORDER' AND source_id=?",i.get("order_id"));
                if("FULFILLED".equals(i.get("order_status"))&&grant==null)gaps++;
                if(grant!=null){if(n(grant,"application_id")!=n(i,"application_id")||n(grant,"api_id")!=n(i,"api_id")||n(grant,"units")!=n(i,"quota_units")||!Objects.equals(grant.get("period_yyyymm"),i.get("period_yyyymm")))gaps++;
                    if(db.one("SELECT s.id FROM fg_api_subscription s JOIN fg_api_quota_balance b ON b.subscription_id=s.id WHERE s.grant_id=? AND b.total_units=?",grant.get("id"),i.get("quota_units"))==null)gaps++;
                    if(slot==null||!"GRANTED".equals(slot.get("state"))||!"ORDER".equals(slot.get("holder_type"))||n(slot,"holder_id")!=n(i,"order_id"))gaps++;
                }
            }
            if(db.one("SELECT id FROM fg_promo_outbox WHERE intent_id=?",i.get("id"))==null)gaps++;
        }if(reserved!=n(p,"reserved")||sold!=n(p,"sold"))gaps++;return Map.of("status",gaps>0?"INTEGRITY_GAP":"REBUILDING".equals(p.get("status"))?"REBUILDING":pending>0?"PENDING":"PROVISIONAL","total",p.get("total_stock"),"reserved",p.get("reserved"),"sold",p.get("sold"),"available",n(p,"total_stock")-n(p,"reserved")-n(p,"sold"),"expectedReserved",reserved,"expectedSold",sold,"integrityGaps",gaps,"intents",intents.size(),"asOfUtc",db.nowUtc());});}
}
